B.Zo=s(["\ubcf8\uc778\uc740 APDI\uac00 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59 \uad50\uc721 \uae30\uc900 \ubc0f \uad50\uc721\uccb4\uacc4\ub97c \uc81c\uacf5\ud558\ub294 \uc804\ubb38\ub2e8\uccb4\uc774\uba70, \uac1c\ubcc4 \uac15\uc0ac\uc640 \uad50\uc721\uae30\uad00\uc774 \ub3c5\ub9bd\uc801\uc73c\ub85c \ud65c\ub3d9\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ub2e4\ub9cc APDI, \uad50\uc721\uae30\uad00, \uac15\uc0ac \ubc0f \uad00\ub828\uc790\uc758 \uad6c\uccb4\uc801\uc778 \ubc95\uc801 \ucc45\uc784\uc740 \uc2e4\uc81c \uacc4\uc57d\uad00\uacc4, \uad50\uc721 \uc6b4\uc601 \ubc0f \uad00\ub9ac\xb7\uac10\ub3c5\uad00\uacc4\uc640 \uad00\ub828 \ubc95\ub839\uc5d0 \ub530\ub77c \ud310\ub2e8\ub428\uc744 \uc774\ud574\ud569\ub2c8\ub2e4."],t.s)
B.anG=new A.e7("\uc81c9\uc870. \uad50\uc721\uae30\uad00\uacfc APDI\uc758 \uad00\uacc4",B.Zo,B.A)
B.a1r=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc758 \uace0\uc720\ud55c \uc704\ud5d8\uacfc \uc77c\ubc18\uc801\uc778 \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\ubcf4\ub2e4 \ub192\uc744 \uc218 \uc788\ub294 \uc704\ud5d8 \uc218\uc900\uc5d0 \ub300\ud55c \uc124\uba85\uc744 \ucda9\ubd84\ud788 \ub4e4\uc5c8\uc73c\uba70, \uc774\ub97c \uc774\ud574\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc790\ubc1c\uc801\uc73c\ub85c \ucc38\uac00\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc801\uc808\ud55c \uad50\uc721, \uc7a5\ube44 \ubc0f \uc548\uc804\uc808\ucc28\uac00 \uc81c\uacf5\ub418\ub354\ub77c\ub3c4 \ubaa8\ub4e0 \uc7a0\uc7ac\uc801 \uc704\ud5d8\uc774 \uc81c\uac70\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc778\uc815\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc790\uc2e0\uc758 \uc790\uaca9, \uacbd\ud5d8 \ubc0f \uc2e0\uccb4\uc801 \ub2a5\ub825\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uad50\uc721 \ubc0f \ud6c8\ub828\uc5d0 \ucc38\uac00\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.anQ=new A.e7("\uc81c10\uc870. \uc790\ubc1c\uc801 \ucc38\uac00 \ubc0f \uc704\ud5d8 \uc218\uc6a9",B.a1r,B.A)
B.a1i=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc5d0 \uc218\ubc18\ub418\ub294 \ubcf8\uc9c8\uc801\uc778 \uc704\ud5d8\uc744 \uc778\uc9c0\ud558\uace0 \uad00\uacc4 \ubc95\ub839\uc5d0\uc11c \ud5c8\uc6a9\ud558\ub294 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc774\ub7ec\ud55c \uc704\ud5d8\uc758 \ubc1c\uc0dd \uac00\ub2a5\uc131\uc744 \uc218\uc6a9\ud569\ub2c8\ub2e4.","\uadf8\ub7ec\ub098 \ubcf8 \ub3d9\uc758\uc11c\ub294 APDI, \uad50\uc721\uae30\uad00, \ub2f4\ub2f9 \uac15\uc0ac \ub610\ub294 \uad00\ub828\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc5d0 \ub530\ub978 \ubc95\uc801 \ucc45\uc784\uc744 \uc77c\uad04\uc801\uc73c\ub85c \uba74\uc81c\ud558\uac70\ub098 \ucc38\uac00\uc790\uc758 \uc815\ub2f9\ud55c \ubc95\uc801 \uad8c\ub9ac\ub97c \ud3ec\uad04\uc801\uc73c\ub85c \ud3ec\uae30\ud558\ub294 \uac83\uc73c\ub85c \ud574\uc11d\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uc0ac\uace0\uc5d0 \ub300\ud55c \ucc45\uc784\uc758 \uc720\ubb34\uc640 \ubc94\uc704\ub294 \uad6c\uccb4\uc801\uc778 \uc0ac\uc2e4\uad00\uacc4 \ubc0f \uad00\ub828 \ubc95\ub839\uc5d0 \ub530\ub77c \ud310\ub2e8\ub429\ub2c8\ub2e4."],t.s)
B.anI=new A.e7("\uc81c11\uc870. \ucc45\uc784 \uba74\ucc45\uc758 \ubc94\uc704",B.a1i,B.A)
B.a0s=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59 \uc0ac\uace0\uac00 \ubc1c\uc0dd\ud558\ub294 \uc7a5\uc18c\uc640 \ud658\uacbd\uc5d0 \ub530\ub77c \uad6c\uc870, \uc758\ub8cc\uae30\uad00 \uc774\uc1a1 \ubc0f \uc804\ubb38 \uc7a0\uc218\uc758\ud559\uc801 \uce58\ub8cc\uac00 \uc9c0\uc5f0\ub420 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc751\uae09\uc0c1\ud669 \ubc1c\uc0dd \uc2dc \uad50\uc721\uae30\uad00 \ub610\ub294 \uad6c\uc870 \ub2f4\ub2f9\uc790\uac00 \ud544\uc694\ud55c \uad6c\uc870 \uc694\uccad, \uc751\uae09\ucc98\uce58 \ubc0f \uc758\ub8cc\uae30\uad00 \uc774\uc1a1\uc744 \uc704\ud55c \uc870\uce58\ub97c \ucde8\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud558\uace0 \uc774\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4."],t.s)
